class Solution:
    def longestSubstring(self, s):
        vowels = set('aeiou')
        n = len(s)

        prefix = 0
        best = {}
        max_len = 0
        start_idx = -1

        for i in range(n):
            if s[i] in vowels:
                prefix -= 2
            else:
                prefix += 1

            if prefix >= 0:
                if i + 1 > max_len:
                    max_len = i + 1
                    start_idx = 0

            if prefix not in best:
                best[prefix] = i

            for k in best:
                if k <= prefix:
                    length = i - best[k]
                    if length > max_len:
                        max_len = length
                        start_idx = best[k] + 1

        return "-1" if max_len == 0 else s[start_idx:start_idx + max_len]
